import { readFileSync } from 'fs';
import { join } from 'path';

// Analyze temporal patterns in FHIR data
const dataPath = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

// Test with a few files
const testFiles = [
  'Zack583_Lockman863_9b55d2b1-d96d-d913-49a7-c7c5de54df6c.json',
  'Rodrigo242_Madrid123_0d20b7c6-147d-ac7e-788b-00a9c9cff8d5.json',
  'Kerry175_Walker122_7fd1151f-a5eb-f3ca-edbc-b6e49f37f4eb.json'
];

console.log('=== FHIR Temporal Analysis ===\n');

for (const filename of testFiles) {
  try {
    const filePath = join(dataPath, filename);
    const data = JSON.parse(readFileSync(filePath, 'utf-8'));

    console.log(`\n--- ${filename} ---`);
    console.log(`Total entries: ${data.entry.length}`);

    // Extract all encounter dates
    const encounters = data.entry.filter((entry: any) => 
      entry.resource.resourceType === 'Encounter'
    );

    if (encounters.length > 0) {
      const dates = encounters.map((enc: any) => enc.resource.period.start);
      const uniqueDates = [...new Set(dates)];

      console.log(`Encounters: ${encounters.length}`);
      console.log(`Unique encounter dates: ${uniqueDates.length}`);
      console.log(`Date range: ${Math.min(...dates)} to ${Math.max(...dates)}`);

      // Check for time pattern
      const times = dates.map((date: string) => date.split('T')[1]);
      const uniqueTimes = [...new Set(times)];
      console.log(`Unique times: ${uniqueTimes.length} (${uniqueTimes.slice(0, 3).join(', ')})`);

      // Check patient birth year
      const patient = data.entry.find((entry: any) => 
        entry.resource.resourceType === 'Patient'
      );
      if (patient) {
        console.log(`Patient birth: ${patient.resource.birthDate}`);
      }

    } else {
      console.log('No encounters found');
    }

  } catch (error) {
    console.error(`Error processing ${filename}:`, error);
  }
}

