import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

// Comprehensive dataset analysis
const dataPath = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

console.log('=== Healthcare EHR Dataset Overview ===\n');

// Get all JSON files
const files = readdirSync(dataPath).filter(f => f.endsWith('.json'));
console.log(`Total files: ${files.length}`);

// File size analysis
const fileSizes = files.map(file => {
  const stats = statSync(join(dataPath, file));
  return {
    name: file,
    size: stats.size,
    sizeMB: Math.round(stats.size / (1024 * 1024) * 10) / 10
  };
});

fileSizes.sort((a, b) => b.size - a.size);

console.log(`\nFile Size Distribution:`);
console.log(`Largest: ${fileSizes[0].name} (${fileSizes[0].sizeMB}MB)`);
console.log(`Smallest: ${fileSizes[fileSizes.length - 1].name} (${fileSizes[fileSizes.length - 1].sizeMB}MB)`);

const sizes = fileSizes.map(f => f.sizeMB);
const avgSize = sizes.reduce((a, b) => a + b, 0) / sizes.length;
console.log(`Average: ${Math.round(avgSize * 10) / 10}MB`);

// Sample analysis on a few files
const sampleFiles = [
  fileSizes[0].name,  // largest
  fileSizes[Math.floor(fileSizes.length / 2)].name,  // median
  fileSizes[fileSizes.length - 1].name  // smallest
];

console.log(`\n=== Sample Analysis ===`);

const resourceTypeCounts: {[key: string]: number} = {};
let totalEntries = 0;

for (const filename of sampleFiles) {
  try {
    const data = JSON.parse(readFileSync(join(dataPath, filename), 'utf-8'));

    console.log(`\n--- ${filename} (${fileSizes.find(f => f.name === filename)?.sizeMB}MB) ---`);
    console.log(`Entries: ${data.entry.length}`);

    // Count resource types
    const resourceTypes: {[key: string]: number} = {};
    data.entry.forEach((entry: any) => {
      const type = entry.resource.resourceType;
      resourceTypes[type] = (resourceTypes[type] || 0) + 1;
      resourceTypeCounts[type] = (resourceTypeCounts[type] || 0) + 1;
    });

    // Show top 5 resource types
    const sortedTypes = Object.entries(resourceTypes)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 5);

    console.log('Top resource types:');
    sortedTypes.forEach(([type, count]) => {
      console.log(`  ${type}: ${count}`);
    });

    totalEntries += data.entry.length;

  } catch (error) {
    console.error(`Error processing ${filename}:`, error);
  }
}

console.log(`\n=== Overall Resource Distribution (Sample) ===`);
const overallSorted = Object.entries(resourceTypeCounts)
  .sort(([,a], [,b]) => b - a);

overallSorted.forEach(([type, count]) => {
  console.log(`${type}: ${count}`);
});

console.log(`\nTotal entries sampled: ${totalEntries}`);
console.log(`Estimated total entries in dataset: ${Math.round(totalEntries * files.length / sampleFiles.length).toLocaleString()}`);
